import json
from collections import defaultdict

test_input = test_input
H, W = 16, 15

def transform_v3(grid):
    """Transform rules based on best understanding."""
    H, W = len(grid), len(grid[0])
    result = [[0] * W for _ in range(H)]

    # Group cells by (color, column range)
    cells_by_color = defaultdict(list)
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != 0:
                cells_by_color[val].append((r, c))

    # Color 8: shift -5 rows
    if 8 in cells_by_color:
        for r, c in cells_by_color[8]:
            nr = max(0, r - 5)
            result[nr][c] = 8

    # Color 2: shift +9 rows
    if 2 in cells_by_color:
        for r, c in cells_by_color[2]:
            nr = min(H - 1, r + 9)
            result[nr][c] = 2

    # Color 1: split by column ranges
    if 1 in cells_by_color:
        # Left block: cols 0-6, shift -2
        for r, c in cells_by_color[1]:
            if c <= 6:
                nr = max(0, r - 2)
                result[nr][c] = 1
        # Right block: cols 12+, shift +5
        for r, c in cells_by_color[1]:
            if c >= 12:
                result[9][14] = 1  # Orphan handled globally
                nr = min(H - 1, r + 5)
                result[nr][c] = 1

    # Color 3: apply left block rules (shift -2)
    if 3 in cells_by_color:
        for r, c in cells_by_color[3]:
            nr = max(0, r - 2)
            result[nr][c] = 3

    return result

